// REUSABLE TEMPLATE — the Parallel-Site Re-Verify Gate.
// See _orchestration/parallel-site-gate.md for the standing discipline.
// Invoke (do NOT edit this file per-use — pass everything via args):
//   Workflow({ scriptPath: "<AVE-Core>/_orchestration/parallel-site-gate.template.js", args: {
//     artifact:      "<human description of the aggregating artifact being banked>",
//     artifact_path: "<file path to read each entry's CURRENT claim from>",
//     repo:          "<repo path for git history>",            // optional
//     entries: [ { label, locate_hint, source_ref, note }, ... ] // the LEAST-SALIENT set
//   }})
// Lane-agnostic: feed it any aggregating artifact (ledger, matrix, multi-file PR, synthesis,
// foreword-anchor set). It fans one INDEPENDENT ave-auditor per entry and returns the verdict roll-up.

export const meta = {
  name: 'parallel-site-gate',
  description: 'Independent-lane re-verify of the least-salient entries of an aggregating artifact against each source latest adjudication, before the artifact is banked (read-past-the-headline / Rule-12 salience-trap gate)',
  phases: [{ title: 'Re-verify', detail: 'one independent ave-auditor per least-salient entry' }],
}

phase('Re-verify')

const A = args || {}
const ENTRIES = Array.isArray(A.entries) ? A.entries : []
if (ENTRIES.length === 0) {
  log('parallel-site-gate: no entries provided in args.entries — nothing to verify. Pass the least-salient set.')
  return { total: 0, faithful: 0, salience_trapped: [], other_mismatch: [], cannot_verify: [], standing_source_traps: [], full: [], error: 'no entries supplied' }
}

const ARTIFACT = A.artifact || '(unnamed aggregating artifact)'
const ARTIFACT_PATH = A.artifact_path || '(artifact path not supplied — locate the entry by its label)'
const REPO = A.repo || '(repo not supplied — infer from the source_ref / paths)'

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['entry_label', 'entry_claim_current', 'source_latest_adjudication', 'has_trailing_demotion', 'source_headline_still_unretracted', 'verdict', 'detail'],
  properties: {
    entry_label: { type: 'string' },
    entry_claim_current: { type: 'string', description: 'verbatim current claim/tag of this entry in the artifact + line number' },
    source_latest_adjudication: { type: 'string', description: 'verbatim quote of the source LATEST verdict/adjudication (the most-recent appended section, NOT the headline) + file:line' },
    has_trailing_demotion: { type: 'boolean', description: 'does the source contain an appended amendment/panel/demotion/Rule-12/superseded/retract section AFTER its original headline verdict' },
    source_headline_still_unretracted: { type: 'boolean', description: 'does the source still carry a loud headline verdict that contradicts a quieter later demotion (a STANDING salience trap for future readers)' },
    verdict: { type: 'string', enum: ['FAITHFUL', 'SALIENCE-TRAPPED', 'OTHER-MISMATCH', 'CANNOT-VERIFY'], description: 'FAITHFUL = entry matches source latest adjudication; SALIENCE-TRAPPED = entry reflects the headline but source has a later demotion the entry missed; OTHER-MISMATCH = disagree for another reason; CANNOT-VERIFY = source not locatable' },
    detail: { type: 'string', description: 'concise reasoning with file:line citations on BOTH sides' },
  },
}

const verdicts = await parallel(ENTRIES.map((e) => () => agent(
  `INDEPENDENT-LANE re-verify of ONE entry in an aggregating artifact. You are a fresh independent auditor — do NOT trust the producer's own "re-verify" claim; check the source yourself.

ARTIFACT being banked: ${ARTIFACT}
ARTIFACT FILE (read each entry's CURRENT claim here): ${ARTIFACT_PATH}
REPO for git history: ${REPO}

ENTRY TO VERIFY: "${e.label}"
${e.locate_hint ? 'How to locate it in the artifact: ' + e.locate_hint : 'Locate it by its label (a heading or row).'}
Source it was built from: ${e.source_ref || '(source not given — find the source doc this entry summarizes)'}
${e.note ? 'SPECIAL NOTE: ' + e.note : ''}

PROCEDURE (cite file:line verbatim for every claim):
1. In the artifact, find this entry (locate by NAME/label — line numbers drift). Quote its current claim/tag verbatim with the actual line number.
2. Locate the SOURCE this entry summarizes. Use \`git show <commit>:<path>\` / \`git log --all\` to read it WITHOUT checking out (do NOT switch branches — other lanes share the repo). If you cannot find it, grep ls-tree / git log --all for a doc whose name contains the entry label.
3. CRITICAL — read PAST the headline. Scan the WHOLE source for any APPENDED section after the original verdict: headings/text matching DEMOTED | PANEL ADJUDICATION | AMENDMENT | Rule 12 | SUPERSEDED | RETRACT | REVISED | walk-back | correction, or a later-dated adjudication. The salience trap is: a loud early headline verdict + a quiet appended demotion. Quote the source's LATEST adjudication verbatim + file:line.
4. Judge: does the entry's current claim faithfully reflect the source's LATEST adjudication (not just its headline)? Set verdict. Also report whether the source's original headline is still un-retracted (a standing trap).

Be terse and exact. Return ONLY the structured object.`,
  { label: `reverify:${e.label}`, agentType: 'ave-auditor', schema: SCHEMA }
)))

// A null return = a sub-auditor that crashed, was skipped, or died. Do NOT silently drop it
// (`.filter(Boolean)`) — that shrinks the denominator and lets an entry pass UNCHECKED through
// the very gate whose job is to prevent that. Coerce each null into an explicit CANNOT-VERIFY row
// so it stays counted, and only report the gate GREEN when EVERY entry came back FAITHFUL.
const rows = verdicts.map((v, i) => v || {
  entry_label: ENTRIES[i].label,
  entry_claim_current: '(not read)',
  source_latest_adjudication: '(not read)',
  has_trailing_demotion: false,
  source_headline_still_unretracted: false,
  verdict: 'CANNOT-VERIFY',
  detail: 'sub-auditor returned null (crashed / skipped / died) — entry was NOT verified; treat as unchecked.',
})
const submitted = ENTRIES.length
const verified = rows.filter(v => v.verdict !== 'CANNOT-VERIFY').length
return {
  submitted,
  verified,
  unchecked: submitted - verified,
  gate_green: rows.every(v => v.verdict === 'FAITHFUL'),   // green ONLY if every entry is FAITHFUL
  total: rows.length,                                       // == submitted, always
  faithful: rows.filter(v => v.verdict === 'FAITHFUL').length,
  salience_trapped: rows.filter(v => v.verdict === 'SALIENCE-TRAPPED').map(v => v.entry_label),
  other_mismatch: rows.filter(v => v.verdict === 'OTHER-MISMATCH').map(v => v.entry_label),
  cannot_verify: rows.filter(v => v.verdict === 'CANNOT-VERIFY').map(v => v.entry_label),
  standing_source_traps: rows.filter(v => v.source_headline_still_unretracted).map(v => v.entry_label),
  full: rows,
}
